    game:$("#game-screen"),bg:$("#location-bg"),hud:$("#hud"),sol:$("#sol-label"),time:$("#time-label"),phase:$("#phase-label"),location:$("#location-label"),place:$("#place-label"),resources:$("#resource-strip"),mission:$("#mission-chip"),missionText:$("#mission-chip-text"),objective:$("#objective-card"),exits:$("#exit-layer"),characters:$("#character-layer"),activities:$("#room-actions"),shade:$("#decision-shade"),decisions:$("#decision-layer"),
    speaker:$("#speaker-name"),dialogue:$("#dialogue-text"),slot:$("#slot-label"),hint:$("#continue-hint"),source:$("#source-button"),quick:$("#quick-menu"),back:$("#back-button"),history:$("#history-button"),auto:$("#auto-button"),skip:$("#skip-button"),qSave:$("#quick-save-button"),qLoad:$("#quick-load-button"),status:$("#status-button"),crew:$("#crew-button"),gameMenu:$("#game-menu-button"),
    panel:$("#panel"),panelClose:$("#panel-close"),panelK:$("#panel-kicker"),panelT:$("#panel-title"),panelB:$("#panel-body"),
